import { resolveClaim } from '../../../shared/scene/claims';
import type { Session } from './session';
import type { Replay } from './replay';

// The memo is the founder's, in their words. Nothing is pre-filled or chosen for them: the decision starts empty. The
// evidence appendix is generated by code from the snapshots the founder actually looked at.

export type Choice = '' | 'A' | 'B' | 'C' | 'not_ready';

export interface Memo {
  choice: Choice;
  reasons: [string, string, string];
  conditions: string;
  watch: string;
}

export const EMPTY_MEMO: Memo = { choice: '', reasons: ['', '', ''], conditions: '', watch: '' };

export const CHOICE_LABEL: Record<Exclude<Choice, ''>, string> = {
  A: 'A: Stay lean (decline the contract)',
  B: 'B: Take it as offered',
  C: 'C: Take it on safer terms',
  not_ready: 'Not ready to decide yet',
};

export interface AppendixLine {
  label: string;
  scenario: string;
  value: string;
  path: string;
  snapshot: string;
  qualification?: string;
}

export function evidenceAppendix(session: Session, replay: Replay | null): AppendixLine[] {
  const refs = [
    ...(['B', 'C'] as const).flatMap((p) => {
      const snap = session.snapshotFor(p, true);
      return [
        { snapshotKey: snap.key, scenario: 'baseline' as const, metric: 'lowest_cash' as const },
        { snapshotKey: snap.key, scenario: 'active' as const, metric: 'lowest_cash' as const },
        { snapshotKey: snap.key, scenario: 'active' as const, metric: 'first_shortfall' as const },
      ];
    }),
  ];
  const lines: AppendixLine[] = [];
  for (const ref of refs) {
    const r = resolveClaim(session.registry, ref);
    if (!r.ok) continue;
    const c = r.claim;
    lines.push({
      label: c.label,
      scenario: c.scenarioLabel,
      value: c.text,
      path: c.pathId,
      snapshot: session.registry.get(ref.snapshotKey)?.inputHash ?? '',
      ...(c.qualification ? { qualification: c.qualification } : {}),
    });
  }
  void replay;
  return lines;
}

export const MEMO_FOOTER =
  'Demo founder: fictional. Synthetic inputs; template values are placeholders, not sourced figures. Not financial advice. One possible future, not a prediction.';
